/** Draws the icons of [IconSet] anywhere. */
object IconPainter {
    private class Part(val kind: String, val path: Path?, val nums: FloatArray?)

    private val cache = HashMap<Icon, List<Part>>()
    private val stroke = Paint(Paint.ANTI_ALIAS_FLAG).apply {
        style = Paint.Style.STROKE
        strokeCap = Paint.Cap.ROUND
        strokeJoin = Paint.Join.ROUND
    }
    private val fill = Paint(Paint.ANTI_ALIAS_FLAG)
    private val dash = DashPathEffect(floatArrayOf(2.2f, 2.6f), 0f)
    private val rect = RectF()

    private fun parts(icon: Icon): List<Part> = cache.getOrPut(icon) {
        val spec = IconSet.specs[icon] ?: return@getOrPut emptyList()
        spec.split('|').map { el ->
            val k = el.substringBefore(':')
            val v = el.substringAfter(':')
            when (k) {
                "s", "sd", "d", "f" -> Part(k, parsePath(v), null)
                else -> Part(k, null, v.trim().split(Regex("\\s+")).map { it.toFloat() }.toFloatArray())
            }
        }
    }

    /** a small SVG path reader: M L H V C Q Z with absolute coordinates */
    fun parsePath(d: String): Path {
        val p = Path()
        val tokens = Regex("[MLHVCQZmlhvcqz]|-?\\d*\\.?\\d+(?:e-?\\d+)?").findAll(d).map { it.value }.toList()
        var i = 0
        var cmd = 'M'
        var x = 0f; var y = 0f
        fun num(): Float = tokens[i++].toFloat()
        while (i < tokens.size) {
            val t = tokens[i]
            if (t.length == 1 && t[0].isLetter()) { cmd = t[0].uppercaseChar(); i++; if (cmd == 'Z') { p.close(); continue } }
            when (cmd) {
                'M' -> { x = num(); y = num(); p.moveTo(x, y); cmd = 'L' }
                'L' -> { x = num(); y = num(); p.lineTo(x, y) }
                'H' -> { x = num(); p.lineTo(x, y) }
                'V' -> { y = num(); p.lineTo(x, y) }
                'C' -> { val a = num(); val b = num(); val c = num(); val e = num(); x = num(); y = num(); p.cubicTo(a, b, c, e, x, y) }
                'Q' -> { val a = num(); val b = num(); x = num(); y = num(); p.quadTo(a, b, x, y) }
                else -> i++
            }
        }
        return p
    }

    /** [sizePx] = full icon box size, centered on (cx, cy). */
    fun draw(canvas: Canvas, icon: Icon, cx: Float, cy: Float, sizePx: Float, color: Int, alpha: Int = 255) {
        val s = sizePx / 24f
        stroke.color = color
        stroke.alpha = alpha
        stroke.strokeWidth = IconSet.STROKE
        fill.color = color
        val tint = (alpha * IconSet.TINT).toInt()
        canvas.save()
        canvas.translate(cx - 12 * s, cy - 12 * s)
        canvas.scale(s, s)
        for (pt in parts(icon)) {
            val n = pt.nums
            when (pt.kind) {
                "s" -> { stroke.pathEffect = null; canvas.drawPath(pt.path!!, stroke) }
                "sd" -> { stroke.pathEffect = dash; canvas.drawPath(pt.path!!, stroke); stroke.pathEffect = null }
                "d" -> { fill.alpha = tint; canvas.drawPath(pt.path!!, fill) }
                "f" -> { fill.alpha = alpha; canvas.drawPath(pt.path!!, fill) }
                "c" -> canvas.drawCircle(n!![0], n[1], n[2], stroke)
                "C" -> { fill.alpha = alpha; canvas.drawCircle(n!![0], n[1], n[2], fill) }
                "D" -> { fill.alpha = tint; canvas.drawCircle(n!![0], n[1], n[2], fill) }
                "rs", "rd", "rf" -> {
                    rect.set(n!![0], n[1], n[0] + n[2], n[1] + n[3])
                    when (pt.kind) {
                        "rs" -> canvas.drawRoundRect(rect, n[4], n[4], stroke)
                        "rd" -> { fill.alpha = tint; canvas.drawRoundRect(rect, n[4], n[4], fill) }
                        else -> { fill.alpha = alpha; canvas.drawRoundRect(rect, n[4], n[4], fill) }
                    }
                }
            }
        }
        canvas.restore()
    }
}
